class TranscriptBuffer:
    def __init__(self, store, owner, session_id):
        self.store = store
        self.owner = owner
        self.session_id = session_id
        self.pending = {}

    def append(self, turn_id, text):
        self.pending.setdefault(turn_id, []).append(text)

    async def flush(self, turn_id):
        payload = tuple(self.pending.get(turn_id, []))
        await self.store.put_if_absent((self.owner, self.session_id, turn_id), payload)
        self.pending.clear()

